import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do I manage YAML files, extra files and backups?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/02.anleitungen/04.yaml-dateien.md"},"headers":[],"relativePath":"adapter/esphome/anleitungen/yaml-dateien.md","filePath":"adapter/esphome/anleitungen/yaml-dateien.md","lastUpdated":1795571670000}'),i={name:"adapter/esphome/anleitungen/yaml-dateien.md"};function l(n,e,d,r,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="how-do-i-manage-yaml-files-extra-files-and-backups" tabindex="-1">How do I manage YAML files, extra files and backups? <a class="header-anchor" href="#how-do-i-manage-yaml-files-extra-files-and-backups" aria-label="Permalink to &quot;How do I manage YAML files, extra files and backups?&quot;">​</a></h1><p><a id="upload-view-delete-yaml-files"></a></p><h2 id="how-do-i-upload-view-or-delete-yaml-files" tabindex="-1">How do I upload, view or delete YAML files? <a class="header-anchor" href="#how-do-i-upload-view-or-delete-yaml-files" aria-label="Permalink to &quot;How do I upload, view or delete YAML files?&quot;">​</a></h2><p>You do this in the tab &quot;YAML Files&quot; of the instance settings. The instance must be running. The files are in the folder <code>iobroker-data/esphome.&lt;instance&gt;</code>, where the dashboard reads them as well.</p><table tabindex="0"><thead><tr><th>Task</th><th>How</th></tr></thead><tbody><tr><td>view</td><td>Choose the file under &quot;YAML file&quot;, &quot;Open in Editor&quot;. The content then appears below in &quot;YAML Content&quot;.</td></tr><tr><td>change</td><td>Open the file, edit &quot;YAML Content&quot;, &quot;Upload File&quot;.</td></tr><tr><td>create</td><td>Fill in &quot;Filename (e.g., my-device.yaml)&quot; and &quot;YAML Content&quot;, &quot;Upload File&quot;.</td></tr><tr><td>delete</td><td>Choose the file under &quot;YAML file&quot;, &quot;Delete File&quot;, confirm.</td></tr><tr><td>reload the list</td><td>&quot;Refresh File List&quot;</td></tr></tbody></table><p>The file name must end in <code>.yaml</code> or <code>.yml</code> and must not contain a folder. &quot;Upload File&quot; overwrites a file with the same name without asking, &quot;Delete File&quot; deletes for good.</p><p><strong>See also:</strong> <a href="#fonts-images-include-files-local">Files other than YAML</a></p><p><a id="fonts-images-include-files-local"></a></p><h2 id="where-do-fonts-images-include-files-and-local-external-components-go" tabindex="-1">Where do fonts, images, include files and local external_components go? <a class="header-anchor" href="#where-do-fonts-images-include-files-and-local-external-components-go" aria-label="Permalink to &quot;Where do fonts, images, include files and local external_components go?&quot;">​</a></h2><p>The tab &quot;YAML Files&quot; only accepts YAML files. Copy fonts, images, include files and local <code>external_components</code> yourself into the folder <code>iobroker-data/esphome.&lt;instance&gt;</code> on the ioBroker host, subfolders are fine.</p><p>In the YAML, give paths relative to this folder, e.g. <code>fonts/arial.ttf</code>. The files must belong to the user ioBroker runs as. If you copied them as another user, <code>iobroker fix</code> corrects the permissions.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">font</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fonts/arial.ttf&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">font_main</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span></code></pre></div><p>With &quot;Use Docker Integration (Beta)&quot; the folder is in the same place, the container sees it as well.</p><p><a id="goes-into-secrets-yaml-happens"></a></p><h2 id="what-goes-into-secrets-yaml-and-what-happens-without-it" tabindex="-1">What goes into secrets.yaml and what happens without it? <a class="header-anchor" href="#what-goes-into-secrets-yaml-and-what-happens-without-it" aria-label="Permalink to &quot;What goes into secrets.yaml and what happens without it?&quot;">​</a></h2><p><code>secrets.yaml</code> holds values that should not be in every device YAML, e.g. Wi-Fi credentials and API keys. It is in the folder <code>iobroker-data/esphome.&lt;instance&gt;</code> next to the device YAMLs. In a device YAML you fetch a value with <code>!secret &lt;name&gt;</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># secrets.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">wifi_ssid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyWiFi&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">wifi_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;Wi-Fi password&gt;&quot;</span></span></code></pre></div><p>The adapter does not create the file. If it is missing, every YAML that uses <code>!secret</code> fails and the dashboard reports an error. Create it in the dashboard via &quot;Secrets&quot; or upload it as <code>secrets.yaml</code> in the tab &quot;YAML Files&quot;.</p><p><a id="devices-back-into-dashboard-after"></a></p><h2 id="how-do-i-get-my-devices-back-into-the-dashboard-after-a-reinstall-or-move" tabindex="-1">How do I get my devices back into the dashboard after a reinstall or move? <a class="header-anchor" href="#how-do-i-get-my-devices-back-into-the-dashboard-after-a-reinstall-or-move" aria-label="Permalink to &quot;How do I get my devices back into the dashboard after a reinstall or move?&quot;">​</a></h2><p>The dashboard shows exactly the YAML files in the folder <code>iobroker-data/esphome.&lt;instance&gt;</code>. If it is empty after a reinstall or a move, the files are missing there.</p><ol><li>Copy the YAML files and <code>secrets.yaml</code> from the backup or the old host into this folder. You can also upload single files in the tab &quot;YAML Files&quot;.</li><li>If the files belong to a user other than ioBroker afterwards, run <code>iobroker fix</code>.</li><li>Reload the dashboard in the browser.</li></ol><p>If you have no YAML left but the device still runs, the dashboard may show it with &quot;Adopt&quot;. This creates a new YAML that you complete.</p><p><strong>See also:</strong> <a href="#back-up-restore-esphome-files">Back up the ESPHome files</a></p><p><a id="back-up-restore-esphome-files"></a></p><h2 id="how-do-i-back-up-and-restore-the-esphome-files" tabindex="-1">How do I back up and restore the ESPHome files? <a class="header-anchor" href="#how-do-i-back-up-and-restore-the-esphome-files" aria-label="Permalink to &quot;How do I back up and restore the ESPHome files?&quot;">​</a></h2><p>Back up the folder <code>iobroker-data/esphome.&lt;instance&gt;</code>. It holds the device YAMLs, <code>secrets.yaml</code> and your own files such as fonts. An update of the adapter leaves the folder in place.</p><p>With the ESPHome option, BackItUp only backs up the YAML files. Back up your own files such as fonts, images or local components yourself.</p><p>The subfolder <code>.esphome</code> contains build files that ESPHome creates again on the next compile. It grows quickly. Leave it out of the backup or delete it first, then the backup stays small. With &quot;Use Docker Integration (Beta)&quot; the compile tools are in a Docker volume, not in this folder.</p><p>This restores it:</p><ol><li>Stop the instance.</li><li>Copy the folder back to <code>iobroker-data/esphome.&lt;instance&gt;</code>.</li><li>Run <code>iobroker fix</code> so the files belong to the ioBroker user.</li><li>Start the instance.</li></ol><p><strong>See also:</strong> <a href="./../erste-schritte/installation#adapter-not-installed-compiled-after">After a restore</a></p>`,32)])])}const f=t(i,[["render",l]]);export{u as __pageData,f as default};
